package com.bank.uc.service;

import com.bank.uc.exception.DuplicatePanException;
import com.bank.uc.model.Account;
import com.bank.uc.repository.AccountRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;

@Service
public class RegistrationService {
    private static final Logger log = LoggerFactory.getLogger(RegistrationService.class);
    private final AccountRepository repo;

    public RegistrationService(AccountRepository repo) { this.repo = repo; }

    public Account register(Account account) {
        try {
            // The clustered PK gives fast id lookups; the unique indexes enforce rules.
            Account saved = repo.save(account);
            log.info("Registered account {} (clustered PK), PAN/email uniqueness enforced",
                     saved.getId());
            return saved;
        } catch (DataIntegrityViolationException ex) {
            // A unique index (ux_accounts_pan or ux_accounts_email) rejected the duplicate
            log.severe("Duplicate PAN or email rejected by unique index: " + ex.getMessage());
            throw new DuplicatePanException("PAN or email already exists", ex);
        }
    }
}
